let raw = '';
const items = $input.all();

if (items.length > 0 && items[0].binary && items[0].binary.data) {
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    raw = buf.toString('utf-8');
  } catch (e) {
    const inline = items[0].binary.data.data;
    if (typeof inline === 'string') {
      raw = Buffer.from(inline, 'base64').toString('utf-8');
    }
  }
}

let data = [];
try {
  data = raw ? JSON.parse(raw) : [];
} catch (e) {
  data = [];
}

const feature_id = 'search_v2';
const now = Date.now();
const window_ms = 60 * 1000;

const recent = data.filter((e) => {
  const ts = new Date(e.timestamp).getTime();
  return Number.isFinite(ts)
    && (now - ts) < window_ms
    && (!e.feature_id || e.feature_id === feature_id);
});

const total = recent.length;
const errors = recent.filter((e) => e.status === 'error').length;
const error_rate = total > 0 ? errors / total : 0;

return [{
  json: {
    feature_id,
    error_rate,
    total,
    errors,
  },
}];

const stats = $('Analyze Logs').item.json;
const feature = $('Get Feature Status').item.json ?? {};

return [{
  json: {
    feature_id: stats.feature_id,
    error_rate: stats.error_rate,
    total: stats.total,
    errors: stats.errors,
    current_status: feature.status ?? null,
    traffic_percentage: feature.traffic_percentage ?? null,
    mcp_error: feature.error ?? null,
  },
}];

